import { makeLocalFixtureSignature, nonceOf } from './packages/wallet-adapter/src/nep413.mjs';
import { makeChallenge, verifyChallengeProof } from './packages/wallet-adapter/src/verify-binding.mjs';
const nonce=nonceOf('codex-negative-review');
const sig=makeLocalFixtureSignature({message:'fixture',nonce,recipient:'showstake.example'});
const base={purpose:'login',domain:'showstake.example',network:'testnet',accountId:'victim.testnet',nonce,message:'fixture'};
const forged={accountId:'victim.testnet',publicKey:sig.publicKey,signature:sig.signature};
const r=verifyChallengeProof({challenge:makeChallenge(base),proof:forged,consumedNonces:new Set(),expectedDomain:'showstake.example',expectedNetwork:'testnet'});
const malformed=makeChallenge({...base,accountId:sig.accountId});
malformed.expiresAtMs=NaN; malformed.issuedAtMs=NaN;
const r2=verifyChallengeProof({challenge:malformed,proof:{...forged,accountId:sig.accountId},consumedNonces:new Set(),expectedDomain:'showstake.example',expectedNetwork:'testnet'});
console.log(JSON.stringify({namedAccountForeignKey:r,nonfiniteTimestamps:r2}));
process.exitCode=(r.ok||r2.ok)?1:0;
